<?php require 'includes/db.php';require 'includes/functions.php';login_required();if($_SERVER['REQUEST_METHOD']==='POST'){$bid=(int)$_POST['book_id'];$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim($_POST['comment']??'');$uid=(int)$_SESSION['user_id'];$s=$conn->prepare('INSERT INTO reviews(user_id,book_id,rating,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment)');$s->bind_param('iiis',$uid,$bid,$rating,$comment);$s->execute();header('Location: book.php?id='.$bid);exit;}header('Location: index.php');?>
